// retries may add at most 10% load, spaced out with backoff and jitter
class RetryBudget(private val ratio: Double = 0.1, private val max: Double = 10.0) {
    private var tokens = 0.0
    @Synchronized fun onRequest() { tokens = minOf(max, tokens + ratio) }
    @Synchronized fun tryRetry(): Boolean = (tokens >= 1.0).also { if (it) tokens -= 1.0 }
}

fun <T> withBudget(budget: RetryBudget, call: () -> T): T {
    budget.onRequest()
    var attempt = 0
    while (true) {
        try {
            return call()
        } catch (e: TimeoutException) {
            if (++attempt == 4 || !budget.tryRetry()) throw e
            Thread.sleep(Random.nextLong(0, minOf(2_000L, 50L shl attempt)))   // full jitter
        }
    }
}
